function envCard(it){
  const cls=LIGHT[it.nginx_status]||'missing';
  const health=it.health==='up'?'<span style="color:var(--ok)">服务中</span>':it.health==='down'?'<span style="color:var(--bad)">不通</span>':'<span style="color:var(--warn)">'+esc(it.health)+'</span>';
  const be=it.backend==='open'?'<span style="color:var(--ok)">通</span>':'<span style="color:var(--bad)">不通</span>';
  return `<div class="env"><div class="head"><b title="${esc(it.display_name||it.project)}">${esc(it.display_name||it.project)}</b><span title="环境 ${esc(it.env)} · ${esc(it.nginx_conf)}"><i class="dot ${cls}"></i>${LABEL[it.nginx_status]||it.nginx_status}</span></div>
  <div><a class="url" title="${esc(it.frontend_url)}" href="${esc(it.frontend_url)}" target="_blank">${esc(it.frontend_url)}</a> ${health}</div>
  <div class="kv" title="网关 ${esc(it.backend_gateway)}">网关 <b>${esc(it.backend_gateway)}</b> ${be}</div>
  <div class="kv" title="dist ${esc(it.dist_root)}">dist <b>${esc(it.dist_root||'-')}</b></div>
  <div class="built">环境 ${esc(it.env)} · 构建 ${esc((it.built_at||'-').slice(0,16))}</div>
   ${acctTable(it)}
   </div>`;}
function render(st){
 document.getElementById('meta').textContent='快照 '+st.generated_at.slice(11,19)+' · '+st.items.length+' 站点 · '+st.orphans.length+' 未收录';
  const by={};
  st.items.forEach(it=>{const p=it.display_name||it.project_key||it.project;(by[p]=by[p]||[]).push(it)});
  let html='';
  for(const p of Object.keys(by).sort()){
   html+=`<section class="group"><h2>${esc(p)}</h2><div class="grid">${by[p].map(envCard).join('')}</div></section>`;
  }
  if(st.orphans.length){
   html+=`<section class="group"><h3>未收录 conf（sites-enabled 中存在但注册表没有，空 conf 标黄）</h3><table><tr><th>文件</th><th>状态</th><th>listen</th><th>大小</th></tr>`+
   st.orphans.map(o=>`<tr class="${o.status==='empty'?'empty-row':''}"><td>${esc(o.name)}</td><td>${LABEL[o.status]||o.status}</td><td>${esc(o.listen_ports?o.listen_ports.join(','):'-')}</td><td>${o.size}</td></tr>`).join('')+`</table></section>`;
  }
  html+=`<section class="group"><h3>最近部署事件</h3><table><tr><th>时间</th><th>项目</th><th>环境</th><th>动作</th><th>结果</th><th>备注</th></tr>`+
  (st.events.length?st.events.map(e=>`<tr><td>${esc(e.ts)}</td><td>${esc(e.project)}</td><td>${esc(e.env)}</td><td>${esc(e.action)}</td><td>${esc(e.result)}</td><td>${esc(e.detail)}</td></tr>`).join(''):'<tr><td colspan="6">暂无</td></tr>')+`</table></section>`;
  document.getElementById('main').innerHTML=html;
}

