const ENV_ORDER=[['local','本地'],['dev','公司开发'],['test','公司测试'],['uat','客户测试'],['prod','生产']];
const ENV_LABEL=Object.fromEntries(ENV_ORDER);
function envCard(it){
  const cls=LIGHT[it.nginx_status]||'missing';
  const health=it.health==='up'?'<span style="color:var(--ok)">服务中</span>':it.health==='down'?'<span style="color:var(--bad)">不通</span>':'<span style="color:var(--warn)">'+esc(it.health)+'</span>';
  const be=it.backend==='open'?'<span style="color:var(--ok)">通</span>':'<span style="color:var(--bad)">不通</span>';
  const el=ENV_LABEL[it.env]||('环境 '+it.env);
  return `<div class="env"><div class="head"><b title="${esc(it.display_name||it.project)} · ${esc(it.env)}">${esc(el)}</b><span title="环境 ${esc(it.env)} · ${esc(it.nginx_conf)}"><i class="dot ${cls}"></i>${LABEL[it.nginx_status]||it.nginx_status}</span></div>
  <div><a class="url" title="${esc(it.frontend_url)}" href="${esc(it.frontend_url)}" target="_blank">:${esc(it.port)} ${esc(it.frontend_url)}</a> ${health}</div>
  <div class="kv" title="网关 ${esc(it.backend_gateway)}">网关 <b>${esc(it.backend_gateway)}</b> ${be}</div>
  <div class="kv" title="dist ${esc(it.dist_root)}">dist <b>${esc(it.dist_root||'-')}</b></div>
  <div class="built">端口 ${esc(it.port)} · 构建 ${esc((it.built_at||'-').slice(0,16))}</div>
   ${acctTable(it)}
   </div>`;}
function placeholder(label){
  return `<div class="env ph"><div class="head"><b>${esc(label)}</b><span>未部署</span></div><div class="kv na">该环境尚未登记到注册表</div></div>`;
}
function render(st){
  document.getElementById('meta').textContent='快照 '+st.generated_at.slice(11,19)+' · '+st.items.length+' 站点 · 五环境视图';
  const by={};
  st.items.forEach(it=>{const p=it.display_name||it.project_key||it.project;(by[p]=by[p]||[]).push(it)});
  let html='';
  for(const p of Object.keys(by).sort()){
    const list=by[p];
    let cards='';
    ENV_ORDER.forEach(([env,label])=>{
      const hit=list.filter(it=>it.env===env);
      cards+=hit.length?hit.map(envCard).join(''):placeholder(label);
    });
    const extra=list.filter(it=>!ENV_ORDER.some(([env])=>env===it.env));
    if(extra.length) cards+=extra.map(envCard).join('');
    html+=`<section class="group"><h2>${esc(p)}</h2><div class="grid">${cards}</div></section>`;
  }
  html+=`<section class="group"><h3>最近部署事件</h3><table><tr><th>时间</th><th>项目</th><th>环境</th><th>动作</th><th>结果</th><th>备注</th></tr>`+
  (st.events.length?st.events.map(e=>`<tr><td>${esc(e.ts)}</td><td>${esc(e.project)}</td><td>${esc(e.env)}</td><td>${esc(e.action)}</td><td>${esc(e.result)}</td><td>${esc(e.detail)}</td></tr>`).join(''):'<tr><td colspan="6">暂无</td></tr>')+`</table></section>`;
  document.getElementById('main').innerHTML=html;
}

